@Override
	public void onUpdate(){

		double extensionSpeed = 0;

		if(!world.isRemote){
			if(lifetime - this.ticksExisted < 15){
				extensionSpeed = -0.01 * (this.ticksExisted - (lifetime - 15));
			}else if(lifetime - this.ticksExisted < 25){
				extensionSpeed = 0;
			}else if(lifetime - this.ticksExisted < 28){
				extensionSpeed = 0.25;
			}

			if(facing != null){ // Will probably be null on the client side, but should never be on the server side
				this.move(MoverType.SELF, this.facing.getXOffset() * extensionSpeed, this.facing.getYOffset() * extensionSpeed,
						this.facing.getZOffset() * extensionSpeed);
			}
		}

		if(lifetime - this.ticksExisted == 30) this.playSound(WizardrySounds.ENTITY_ICE_SPIKE_EXTEND, 1, 2.5f);

		if(!this.world.isRemote){
			for(Object entity : this.world.getEntitiesWithinAABBExcludingEntity(this, this.getEntityBoundingBox())){
				if(entity instanceof EntityLivingBase && this.isValidTarget((EntityLivingBase)entity)){
					DamageSource source = this.getCaster() == null ? DamageSource.MAGIC : MagicDamage.causeDirectMagicDamage(this.getCaster(), DamageType.FROST);
					// Potion effect only gets added if the damage succeeded
					// We DO want knockback here or the entity gets stuck on the spike, which is a bit of a cheat
					if(((EntityLivingBase)entity).attackEntityFrom(source, Spells.ice_spikes.getProperty(Spell.DAMAGE).floatValue() * this.damageMultiplier))
						((EntityLivingBase)entity).addPotionEffect(new PotionEffect(WizardryPotions.frost,
								Spells.ice_spikes.getProperty(Spell.EFFECT_DURATION).intValue(),
								Spells.ice_spikes.getProperty(Spell.EFFECT_STRENGTH).intValue()));
				}
			}
		}

		super.onUpdate();
	}

@Override
	protected boolean spawnConstruct(World world, double x, double y, double z, EnumFacing side, EntityLivingBase caster, SpellModifiers modifiers){

		if(side == null) return false;

		BlockPos blockHit = new BlockPos(x, y, z);
		if(side.getAxisDirection() == EnumFacing.AxisDirection.NEGATIVE) blockHit = blockHit.offset(side);

		if(world.getBlockState(blockHit).isNormalCube()) return false;

		Vec3d origin = new Vec3d(x, y, z);

		Vec3d pos = origin.add(new Vec3d(side.getOpposite().getDirectionVec()));

		// Now always spawns a spike exactly at the position aimed at
		super.spawnConstruct(world, pos.x, pos.y, pos.z, side, caster, modifiers);
		// -1 because of the one spawned above
		int quantity = (int)(getProperty(ICE_SPIKE_COUNT).floatValue() * modifiers.get(WizardryItems.blast_upgrade)) - 1;

		float maxRadius = getProperty(EFFECT_RADIUS).floatValue() * modifiers.get(WizardryItems.blast_upgrade);

		for(int i=0; i<quantity; i++){

			double radius = 0.5 + world.rand.nextDouble() * (maxRadius - 0.5);

			// First, generate a random vector of length radius with a z component of zero
			// Then rotate it so that what was south is now the side that was hit
			Vec3d offset = Vec3d.fromPitchYaw(world.rand.nextFloat() * 180 - 90, world.rand.nextBoolean() ? 0 : 180)
					.scale(radius).rotateYaw(side.getHorizontalAngle() * (float)Math.PI/180).rotatePitch(GeometryUtils.getPitch(side) * (float)Math.PI/180);

			if(side.getAxis().isHorizontal()) offset = offset.rotateYaw((float)Math.PI/2);

			Integer surface = BlockUtils.getNearestSurface(world, new BlockPos(origin.add(offset)), side,
					(int)maxRadius, true, BlockUtils.SurfaceCriteria.basedOn(IBlockState::isNormalCube));

			if(surface != null){
				Vec3d vec = GeometryUtils.replaceComponent(origin.add(offset), side.getAxis(), surface)
						.subtract(new Vec3d(side.getDirectionVec()));
				super.spawnConstruct(world, vec.x, vec.y, vec.z, side, caster, modifiers);
			}
		}

		return true;
	}

@Override
	protected void addConstructExtras(EntityIceSpike construct, EnumFacing side, EntityLivingBase caster, SpellModifiers modifiers){
		// In this particular case, lifetime is implemented as a delay instead so is treated differently.
		construct.lifetime = 30 + construct.world.rand.nextInt(15);
		construct.setFacing(side);
	}

@Override
        public void tick() {
            checkForMobsTime--;
            LivingEntity target = GammaroachEntity.this.getTarget();
            if (target != null && target.isAlive()) {
                if (checkForMobsTime < 0) {
                    checkForMobsTime = 120 + GammaroachEntity.this.random.nextInt(100);
                    Predicate<Entity> monsterAway = (animal) -> animal instanceof Enemy && !(animal instanceof GammaroachEntity) && animal.distanceTo(target) > 5 && !animal.isPassenger();
                    List<Mob> list = GammaroachEntity.this.level().getEntitiesOfClass(Mob.class, GammaroachEntity.this.getBoundingBox().inflate(30, 12, 30), EntitySelector.NO_SPECTATORS.and(monsterAway));
                    list.sort(Comparator.comparingDouble(GammaroachEntity.this::distanceToSqr));
                    if (!list.isEmpty()) {
                        pickupMonster = list.get(0);
                    }
                }
                if (pickupMonster == null || pickupMonster.isPassengerOfSameVehicle(GammaroachEntity.this)) {
                    GammaroachEntity.this.getNavigation().moveTo(target, 1.0D);
                    GammaroachEntity.this.lookAt(target, 180, 30);
                    if (GammaroachEntity.this.distanceTo(target) < 1.5F + target.getBbWidth()) {
                        if (GammaroachEntity.this.getAnimation() == NO_ANIMATION) {
                            GammaroachEntity.this.setAnimation(GammaroachEntity.ANIMATION_RAM);
                        } else if (GammaroachEntity.this.getAnimation() == GammaroachEntity.ANIMATION_RAM && GammaroachEntity.this.getAnimationTick() > 8 && GammaroachEntity.this.getAnimationTick() < 15) {
                            GammaroachEntity.this.playSound(ACSoundRegistry.GAMMAROACH_ATTACK.get());
                            target.hurt(damageSources().mobAttack(GammaroachEntity.this), (float) GammaroachEntity.this.getAttributeValue(Attributes.ATTACK_DAMAGE));
                        }
                        if (pickupMonster != null) {
                            pickupMonster.stopRiding();
                            pickupMonster = null;
                        }
                    }
                } else if (pickupMonster.isAlive() && (!pickupMonster.isPassenger())) {
                    GammaroachEntity.this.getNavigation().moveTo(pickupMonster, 1.0D);
                    GammaroachEntity.this.lookAt(pickupMonster, 180, 30);
                    if (GammaroachEntity.this.distanceTo(pickupMonster) < 1.5F + pickupMonster.getBbWidth()) {
                        pickupMonster.startRiding(GammaroachEntity.this, true);
                        pickupMonster.hurt(damageSources().cactus(), 1);
                    }
                } else {
                    pickupMonster = null;
                }
            }
        }

@Override
        public boolean canUse() {
            LivingEntity target = GammaroachEntity.this.getTarget();
            return target != null && target.isAlive();
        }

public void stop() {
            if (pickupMonster != null) {
                if (pickupMonster.isPassengerOfSameVehicle(GammaroachEntity.this)) {
                    pickupMonster.stopRiding();
                }
                pickupMonster = null;
                checkForMobsTime = 20;
            }
        }

public void onUse(World world, BlockPos pos, PlayerEntity player, Hand hand) {
		if (!getCachedState().get(Properties.WATERLOGGED)) {
			ItemStack stack = player.getStackInHand(hand);
			if (getCachedState().get(Properties.LIT)) {
				world.setBlockState(pos, getCachedState().with(Properties.LIT, false));
				world.playSound(null, pos, SoundEvents.BLOCK_FIRE_EXTINGUISH, SoundCategory.BLOCKS, 1, 2);
				reset(hasIncense);
				syncBrazier();
			} else {
				if (stack.getItem() instanceof FlintAndSteelItem) {
					world.setBlockState(pos, getCachedState().with(Properties.LIT, true));
					world.playSound(null, pos, SoundEvents.ITEM_FLINTANDSTEEL_USE, SoundCategory.BLOCKS, 1, 1);
					stack.damage(1, player, stackUser -> stackUser.sendToolBreakStatus(hand));
					IncenseRecipe foundIncenseRecipe = world.getRecipeManager().listAllOfType(BWRecipeTypes.INCENSE_RECIPE_TYPE).stream().filter(recipe -> recipe.matches(this, world)).findFirst().orElse(null);
					if (foundIncenseRecipe != null) {
						incenseRecipe = foundIncenseRecipe;
						timer = -6000;
						hasIncense = true;
						syncBrazier();
					} else if (BWConfig.enableCurses) {
						CurseRecipe foundCurseRecipe = world.getRecipeManager().listAllOfType(BWRecipeTypes.CURSE_RECIPE_TYPE).stream().filter(recipe -> recipe.matches(this, world)).findFirst().orElse(null);
						if (foundCurseRecipe != null && getTarget() != null) {
							curseRecipe = foundCurseRecipe;
							timer = -100;
							syncBrazier();
						}
					}
				} else if (!stack.isEmpty()) {
					int firstEmpty = getFirstEmptySlot();
					if (firstEmpty != -1) {
						setStack(firstEmpty, stack.split(1));
						syncBrazier();
					}
				} else {
					reset(hasIncense);
					syncBrazier();
				}
			}
		}
		markDirty();
	}

public static void tick(World world, BlockPos pos, BlockState state, BrazierBlockEntity blockEntity) {
		if (world != null) {
			if (!blockEntity.loaded) {
				if (!world.isClient && state.get(Properties.LIT)) {
					blockEntity.incenseRecipe = world.getRecipeManager().listAllOfType(BWRecipeTypes.INCENSE_RECIPE_TYPE).stream().filter(recipe -> recipe.matches(blockEntity, world)).findFirst().orElse(null);
					if (BWConfig.enableCurses) {
						blockEntity.curseRecipe = world.getRecipeManager().listAllOfType(BWRecipeTypes.CURSE_RECIPE_TYPE).stream().filter(recipe -> recipe.matches(blockEntity, world)).findFirst().orElse(null);
					}
					blockEntity.hasIncense = blockEntity.incenseRecipe != null;
					blockEntity.markDirty();
					blockEntity.syncBrazier();
				}
				blockEntity.loaded = true;
			}
			if (blockEntity.timer < 0) {
				blockEntity.timer++;
				if (world.isClient) {
					if (world.random.nextBoolean()) {
						world.addParticle(blockEntity.hasIncense ? (ParticleEffect) BWParticleTypes.INCENSE_SMOKE : ParticleTypes.LARGE_SMOKE, pos.getX() + 0.5 + MathHelper.nextDouble(world.random, -0.2, 0.2), pos.getY() + (state.get(Properties.HANGING) ? 0.4 : 1.25), pos.getZ() + 0.5 + MathHelper.nextDouble(world.random, -0.2, 0.2), 0, 0.05, 0);
					}
				} else if (blockEntity.timer == 0) {
					boolean clear = blockEntity.hasIncense;
					if (blockEntity.curseRecipe != null) {
						PlayerEntity closestPlayer = world.getClosestPlayer(pos.getX() + 0.5, pos.getY() + 0.5, pos.getZ() + 0.5, 24, false);
						if (blockEntity.altarPos != null && ((WitchAltarBlockEntity) world.getBlockEntity(blockEntity.altarPos)).drain(blockEntity.curseRecipe.cost, false)) {
							if (closestPlayer != null) {
								Entity target = blockEntity.getTarget();
								if (target instanceof PlayerEntity player && BewitchmentAPI.getFamiliar(player) == BWEntityTypes.RAVEN && world.random.nextBoolean()) {
									target = closestPlayer;
								}
								if (target instanceof LivingEntity livingEntity) {
									PoppetData poppetData = BewitchmentAPI.getPoppet(world, BWObjects.CURSE_POPPET, target);
									if (!poppetData.stack().isEmpty() && poppetData.stack().hasNbt() && !poppetData.stack().getNbt().getBoolean("Cursed")) {
										poppetData.stack().getNbt().putString("Curse", BWRegistries.CURSE.getId(blockEntity.curseRecipe.curse).toString());
										poppetData.stack().getNbt().putBoolean("Cursed", true);
										TaglockItem.removeTaglock(poppetData.stack());
										poppetData.update(world, true);
									} else {
										int duration = 168000;
										if (BewitchmentAPI.getFamiliar(closestPlayer) == BWEntityTypes.RAVEN) {
											duration *= 2;
										}
										if (target instanceof PlayerEntity player && TrinketsApi.getTrinketComponent((LivingEntity) target).get().isEquipped(BWObjects.NAZAR) && BewitchmentAPI.drainMagic(player, 50, false)) {
											duration /= 2;
										}
										BWComponents.CURSES_COMPONENT.get(livingEntity).addCurse(new Curse.Instance(blockEntity.curseRecipe.curse, duration));
									}
									world.playSound(null, pos, BWSoundEvents.ENTITY_GENERIC_CURSE, SoundCategory.BLOCKS, 1, 1);
									clear = true;
								}
							} else {
								world.playSound(null, pos, BWSoundEvents.BLOCK_BRAZIER_FAIL, SoundCategory.BLOCKS, 1, 1);
								if (closestPlayer != null) {
									String entityName = "";
									for (int i = 0; i < blockEntity.size(); i++) {
										ItemStack stack = blockEntity.getStack(i);
										if (stack.getItem() instanceof TaglockItem && TaglockItem.hasTaglock(stack)) {
											entityName = TaglockItem.getTaglockName(stack);
											break;
										}
									}
									closestPlayer.sendMessage(Text.translatable(Bewitchment.MOD_ID + ".message.invalid_entity", entityName), true);
								}
							}
						} else {
							if (closestPlayer != null) {
								world.playSound(null, pos, BWSoundEvents.BLOCK_BRAZIER_FAIL, SoundCategory.BLOCKS, 1, 1);
								closestPlayer.sendMessage(Text.translatable(Bewitchment.MOD_ID + ".message.insufficent_altar_power"), true);
							}
						}
					}
					blockEntity.reset(clear);
					blockEntity.syncBrazier();
				}
			}
		}
	}

private Entity getTarget() {
		if (world != null && !world.isClient) {
			for (int i = 0; i < size(); i++) {
				Entity entity = BewitchmentAPI.getTaglockOwner(world, getStack(i));
				if (entity != null) {
					return entity;
				}
			}
		}
		return null;
	}

private void reset(boolean clear) {
		if (world != null) {
			if (clear) {
				cleanInventory();
			}
			ItemScatterer.spawn(world, pos.up(getCachedState().get(Properties.HANGING) ? 0 : 1), this);
			incenseRecipe = null;
			curseRecipe = null;
			timer = 0;
			hasIncense = false;
		}
	}

private void cleanInventory() {
		for (int i = 0; i < inventory.size(); i++) {
			ItemStack stack = getStack(i);
			if (stack.isDamageable()) {
				if (stack.damage(1, world.random, null) && stack.getDamage() == stack.getMaxDamage()) {
					stack.decrement(1);
				}
			} else {
				Item item = stack.getItem();
				setStack(i, item.hasRecipeRemainder() ? new ItemStack(item.getRecipeRemainder()) : ItemStack.EMPTY);
			}
		}
	}

@Override
	public void readNbt(NbtCompound nbt) {
		super.readNbt(nbt);
		if (nbt.contains("AltarPos")) {
			setAltarPos(BlockPos.fromLong(nbt.getLong("AltarPos")));
		}
		inventory.clear();
		Inventories.readNbt(nbt, inventory);
		timer = nbt.getInt("Timer");
		hasIncense = nbt.getBoolean("HasIncense");
	}

@Override
	protected void writeNbt(NbtCompound nbt) {
		super.writeNbt(nbt);
		if (getAltarPos() != null) {
			nbt.putLong("AltarPos", getAltarPos().asLong());
		}
		Inventories.writeNbt(nbt, inventory);
		nbt.putInt("Timer", timer);
		nbt.putBoolean("HasIncense", hasIncense);
	}

public void tick() {
        if (this.level != null) {
            ++this.tickCount;
            if (this.level instanceof ServerLevel serverLevel) {
                int radius = 8 + this.getEnchantments().getOrDefault(ModEnchantments.RADIUS.get(), 0);
                if (this.target == null) {
                    for (LivingEntity livingEntity : serverLevel.getEntitiesOfClass(LivingEntity.class, new AABB(this.worldPosition).inflate(radius * 2))) {
                        if (EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(livingEntity) && livingEntity.distanceToSqr(this.getBlockPos().getCenter()) <= Mth.square(radius)) {
                            boolean flag = livingEntity.getHealth() >= livingEntity.getMaxHealth() * 0.25F;
                            if (this.getTrueOwner() != null) {
                                flag &= !MobUtil.areAllies(this.getTrueOwner(), livingEntity);
                            } else {
                                flag &= !this.isAllyWith(livingEntity);
                            }
                            if (flag) {
                                this.target = livingEntity;
                            }
                        }
                    }
                } else {
                    if (!this.target.isAlive() || this.target.getHealth() < this.target.getMaxHealth() * 0.25F || this.target.distanceToSqr(this.getBlockPos().getCenter()) > Mth.square(radius)) {
                        this.attackTick = 0;
                        this.target = null;
                    } else {
                        ++this.attackTick;
                        if (this.attackTick % 20 == 0) {
                            Vec3 vector3d1 = this.getBlockPos().getCenter();
                            DamageSource damageSource = this.getTrueOwner() != null ? ModDamageSource.soulLeech(this.getTrueOwner(), this.getTrueOwner()) : this.level.damageSources().magic();
                            this.target.addEffect(new MobEffectInstance(GoetyEffects.CURSED.get(), 10, 0, false, false));
                            if (this.target.hurt(damageSource, this.target.getMaxHealth() * 0.1F)) {
                                ColorUtil colorUtil1 = new ColorUtil(0x5038dd);
                                serverLevel.sendParticles(new SpirallingParticleOption(1.0F, colorUtil1.red, colorUtil1.green, colorUtil1.blue, 5), vector3d1.x, vector3d1.y, vector3d1.z, 1, 0.0D, 0.0D, 0.0D, 1.0D);
                                Vec3 vec3 = new Vec3(this.target.getX(), this.target.getY() + (this.target.getBbHeight() / 2.0F), this.target.getZ());
                                serverLevel.sendParticles(new GatherTrailParticleOption(colorUtil1, vector3d1), vec3.x, vec3.y, vec3.z, 0, 0.0F, 0.0F, 0.0F, 0.5F);
                                for (int i = 0; i < 8; ++i) {
                                    Vec3 vec31 = new Vec3(this.target.getRandomX(1.0F), this.target.getRandomY(), this.target.getRandomZ(1.0F));
                                    serverLevel.sendParticles(new AbsorbTrailParticleOption(vector3d1, 0x5038dd, 10), vec31.x, vec31.y, vec31.z, 1, 0.0, 0.0, 0.0, 0.0);
                                }
                                this.level.playSound(null, this.worldPosition, ModSounds.SOUL_EAT.get(), SoundSource.BLOCKS, 1.0F, 1.0F);
                                if (this.getTrueOwner() instanceof Player player) {
                                    if (SEHelper.getSoulGiven(this.target) > 0) {
                                        int enchantment = this.getEnchantments().getOrDefault(ModEnchantments.SOUL_EATER.get(), 0);
                                        int soulEater = Mth.clamp(enchantment + 1, 1, 10);
                                        SEHelper.increaseSouls(player, MainConfig.BlackCrystalSouls.get() * soulEater);
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

@Nullable
    public LivingEntity getTrueOwner() {
        if (this.level != null) {
            if (!this.level.isClientSide){
                UUID uuid = this.getOwnerUUID();
                return uuid == null ? null : EntityFinder.getLivingEntityByUuiD(uuid);
            } else {
                int id = this.getOwnerId();
                return id <= -1 ? null : this.level.getEntity(this.getOwnerId()) instanceof LivingEntity living ? living : null;
            }
        } else {
            return null;
        }
    }

public void tick() {
        super.tick();
        this.prevGroundProgress = groundProgress;
        this.yBodyRot = this.getYRot();
        if (this.onGround() && groundProgress < 5F) {
            groundProgress++;
        }
        if (!this.onGround() && groundProgress > 0F) {
            groundProgress--;
        }
        if (!level().isClientSide) {
            Entity winch = getWinch();
            if (winch == null) {
                LivingEntity created = createWinch();
                level().addFreshEntity(created);
                this.setWinchUUID(created.getUUID());
                this.entityData.set(WINCH_ID, created.getId());
            } else {
                if (winch instanceof BoundroidWinchEntity winchEntity) {
                    winchEntity.linkWithHead(this);
                }
            }
            LivingEntity target = this.getTarget();
            if (target != null && target.isAlive()) {
                Vec3 distanceVec = target.position().subtract(this.position());
                if (distanceVec.horizontalDistance() < 1.2 && stopSlammingFor == 0) {
                    this.setSlamming(true);
                }
            }
            if (this.isSlamming()) {
                this.setDeltaMovement(new Vec3(this.getDeltaMovement().x, -1, this.getDeltaMovement().z));
                if (this.onGround()) {
                    this.setSlamming(false);
                    this.playSound(ACSoundRegistry.BOUNDROID_SLAM.get());
                    this.stayOnGroundFor = 10;
                    this.stopSlammingFor = 30 + random.nextInt(20);
                    this.level().broadcastEntityEvent(this, (byte) 45);
                    AABB bashBox = new AABB(-1.5F, -2F, -1.5F, 1.5F, 1F, 1.5F);
                    bashBox = bashBox.move(this.position());
                    for (Entity entity : this.level().getEntitiesOfClass(LivingEntity.class, bashBox)) {
                        if (!isAlliedTo(entity) && !(entity instanceof BoundroidEntity) && !(entity instanceof BoundroidWinchEntity)) {
                            entity.hurt(damageSources().mobAttack(this), 5);
                        }
                    }
                }
            }
        }else if(isAlive()){
            AlexsCaves.PROXY.playWorldSound(this, (byte) 12);
        }
        if (stopSlammingFor > 0) {
            stopSlammingFor--;
        }
        if (stayOnGroundFor > 0) {
            stayOnGroundFor--;
        }
    }

