private void tick(Purpoid purpoid) {
			if ((purpoid.isEndimationPlaying(EEPlayableEndimations.PURPOID_TELEPORT_TO) || purpoid.isEndimationPlaying(EEPlayableEndimations.PURPOID_FAST_TELEPORT_TO)) && purpoid.getAnimationTick() == 10) {
				this.teleportToDestination(purpoid);
			} else if (purpoid.isEndimationPlaying(EEPlayableEndimations.PURPOID_TELEPORT_FROM)) {
				purpoid.setDeltaMovement(Vec3.ZERO);
			}
		}

private void teleportToDestination(Purpoid purpoid) {
			Vec3 destination = this.destination;
			if (destination != null) {
				Entity ridingEntity = purpoid.getVehicle();
				if (ridingEntity != null) {
					ridingEntity.teleportToWithTicket(destination.x, destination.y, destination.z);
				} else {
					NetworkUtil.teleportEntity(purpoid, destination.x, destination.y, destination.z);
				}
				this.destination = null;
			}
		}

public void beginTeleportation(Purpoid purpoid, Vec3 destination, boolean fast) {
			NetworkUtil.setPlayingAnimation(purpoid, fast ? EEPlayableEndimations.PURPOID_FAST_TELEPORT_TO : EEPlayableEndimations.PURPOID_TELEPORT_TO);
			this.destination = destination;
		}

public void beginTeleportation(Purpoid purpoid, BlockPos destination, boolean fast) {
			this.beginTeleportation(purpoid, new Vec3(destination.getX() + 0.5D, purpoid.isBaby() ? destination.getY() + 0.25F : destination.getY(), destination.getZ() + 0.5D), fast);
		}

public boolean isTeleporting() {
			return this.destination != null;
		}

@Override
    public void tick() {
        float progress = this.getProgress();
        this.prevProgress = progress;
        if(tickCount < 1){
            onJoinWorld();
        }else if(tickCount == 1){
            if(!this.level().isClientSide){
                this.playSound(AMSoundRegistry.TENDON_WHIP.get(),1.0F, 0.8F + this.random.nextFloat() * 0.4F);
            }
        }
        super.tick();
        Entity creator = getCreatorEntity();
        Entity current = getToEntity();
        if(progress < MAX_EXTEND_TIME && !this.isRetracting()){
            this.setProgress(progress + 1);
        }
        if(progress > 0F && this.isRetracting()){
            this.setProgress(progress - 1);
        }
        if(progress == 0F && this.isRetracting()){
            Entity from = this.getFromEntity();
            if(from instanceof EntityTendonSegment){
                EntityTendonSegment tendonSegment = (EntityTendonSegment) from;
                tendonSegment.setRetracting(true);
                updateLastTendon(tendonSegment);
            }else{
                updateLastTendon(null);
            }

            this.remove(RemovalReason.DISCARDED);
        }
        if (creator instanceof LivingEntity) {
            if (current != null) {
                Vec3 target = new Vec3(current.getX(), current.getY(0.4F), current.getZ());
                Vec3 lerp = target.subtract(this.position());
                this.setDeltaMovement(lerp.scale(0.5F));
                if(!this.level().isClientSide){
                    if(!hasTouched && progress >= MAX_EXTEND_TIME){
                        hasTouched = true;
                        Entity entity = getCreatorEntity();
                        if(entity instanceof LivingEntity){
                            if(current != creator && current.hurt(damageSources().mobProjectile(this, (LivingEntity)entity), (float) getDamageFor((LivingEntity)creator, (LivingEntity)entity))){
                                this.doEnchantDamageEffects((LivingEntity) creator, entity);
                            }
                        }
                    }
                }
            }
        }
        Vec3 vector3d = this.getDeltaMovement();
        if(!this.level().isClientSide){
            if(!hasChained){
                if(this.getTargetsHit() > 3){
                    this.setRetracting(true);
                }else if(creator instanceof LivingEntity && this.getProgress() >= MAX_EXTEND_TIME) {
                    Entity closestValid = null;
                    for (Entity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(8.0D))) {
                        if (!entity.equals(creator) && !previouslyTouched.contains(entity) && isValidTarget((LivingEntity) creator, entity) && this.hasLineOfSight(entity)) {
                            if (closestValid == null || this.distanceTo(entity) < this.distanceTo(closestValid)) {
                                closestValid = entity;
                            }
                        }
                    }
                    if(closestValid != null){
                        createChain(closestValid);
                        hasChained = true;
                    }else{
                        this.setRetracting(true);
                    }
                }
            }
        }
        final double d0 = this.getX() + vector3d.x;
        final double d1 = this.getY() + vector3d.y;
        final double d2 = this.getZ() + vector3d.z;
        this.setDeltaMovement(vector3d.scale(0.99F));
        this.setPos(d0, d1, d2);
    }

private void createChain(Entity closestValid) {
        this.entityData.set(HAS_CLAW, false);
        EntityTendonSegment child = AMEntityRegistry.TENDON_SEGMENT.get().create(this.level());
        child.previouslyTouched = new ArrayList<>(previouslyTouched);
        child.previouslyTouched.add(closestValid);
        child.setCreatorEntityUUID(this.getCreatorEntityUUID());
        child.setFromEntityID(this.getId());
        child.setToEntityID(closestValid.getId());
        child.setPos(closestValid.getX(), closestValid.getY(0.4F), closestValid.getZ());
        child.setTargetsHit(this.getTargetsHit() + 1);
        updateLastTendon(child);
        child.setHasGlint(this.hasGlint());
        this.level().addFreshEntity(child);
    }

private void onJoinWorld(){
        Entity creator = getCreatorEntity();
        if(creator == null){
            creator = level().getPlayerByUUID(this.getCreatorEntityUUID());
        }
        Entity prior = getFromEntity();
        if(creator instanceof Player){
            Player player = (Player)creator;
            ItemStack stack = player.getItemInHand(InteractionHand.MAIN_HAND).is(AMItemRegistry.TENDON_WHIP.get()) ? player.getItemInHand(InteractionHand.MAIN_HAND) : player.getItemInHand(InteractionHand.OFF_HAND);
            if(stack.is(AMItemRegistry.TENDON_WHIP.get())){
                this.setHasGlint(stack.hasFoil());
            }
            float dmg = 2;
            if(prior instanceof EntityTendonSegment){
                dmg = Math.max(((EntityTendonSegment)prior).getBaseDamage() - 1, 2);
            }else{
                dmg = (float)getDamageForItem(stack);
            }
            this.entityData.set(DAMAGE, dmg);
        }
    }

private void updateLastTendon(EntityTendonSegment lastTendon){
        Entity creator = getCreatorEntity();
        if(creator == null){
            creator = level().getPlayerByUUID(this.getCreatorEntityUUID());
        }
        if(creator instanceof LivingEntity){
            TendonWhipUtil.setLastTendon((LivingEntity)creator, lastTendon);
        }
    }

public Entity getCreatorEntity() {
        UUID uuid = getCreatorEntityUUID();
        if(uuid != null && !this.level().isClientSide){
            return ((ServerLevel) level()).getEntity(uuid);
        }
        return null;
    }

public Entity getFromEntity() {
        return getFromEntityID() == -1 ? null : this.level().getEntity(getFromEntityID());
    }

public Entity getToEntity() {
        return getToEntityID() == -1 ? null : this.level().getEntity(getToEntityID());
    }

private double getDamageFor(LivingEntity creator, LivingEntity entity) {
        ItemStack stack = creator.getItemInHand(InteractionHand.MAIN_HAND).is(AMItemRegistry.TENDON_WHIP.get()) ? creator.getItemInHand(InteractionHand.MAIN_HAND) : creator.getItemInHand(InteractionHand.OFF_HAND);
        double dmg = this.getBaseDamage();
        if(stack.is(AMItemRegistry.TENDON_WHIP.get())){
            dmg += EnchantmentHelper.getDamageBonus(stack, entity.getMobType());
        }
        return dmg;
    }

private boolean hasLineOfSight(Entity entity) {
        if (entity.level() != this.level()) {
            return false;
        } else {
            Vec3 vec3 = new Vec3(this.getX(), this.getEyeY(), this.getZ());
            Vec3 vec31 = new Vec3(entity.getX(), entity.getEyeY(), entity.getZ());
            if (vec31.distanceTo(vec3) > 128.0D) {
                return false;
            } else {
                return this.level().clip(new ClipContext(vec3, vec31, ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, this)).getType() == HitResult.Type.MISS;
            }
        }
    }

public static void setLastTendon(LivingEntity entity, EntityTendonSegment tendon) {
        CompoundTag tag = CitadelEntityData.getOrCreateCitadelTag(entity);
        if (tendon == null) {
            tag.remove(LAST_TENDON_UUID);
            tag.putInt(LAST_TENDON_ID, -1);
        } else {
            tag.putUUID(LAST_TENDON_UUID, tendon.getUUID());
            tag.putInt(LAST_TENDON_ID, tendon.getId());
        }
        sync(entity, tag);
    }

public static EntityTendonSegment getLastTendon(LivingEntity player) {
        UUID uuid = getLastTendonUUID(player);
        int id = getLastTendonId(player);
        if (!player.level().isClientSide) {
            if (uuid != null) {
                Entity e = player.level().getEntity(id);
                return e instanceof EntityTendonSegment ? (EntityTendonSegment) e : null;
            }
        } else {
            if (id != -1) {
                Entity e = player.level().getEntity(id);
                return e instanceof EntityTendonSegment ? (EntityTendonSegment) e : null;
            }
        }
        return null;
    }

public static boolean canLaunchTendons(Level level, LivingEntity player) {
        EntityTendonSegment last = getLastTendon(player);
        if (last != null) {
            return last.isRemoved() || last.distanceTo(player) > 30;
        }
        return true;
    }

public static void retractFarTendons(Level level, LivingEntity player) {
        EntityTendonSegment last = getLastTendon(player);
        if (last != null) {
            last.remove(Entity.RemovalReason.DISCARDED);
            setLastTendon(player, null);
        }
    }

private static void sync(LivingEntity enchanted, CompoundTag tag) {
        CitadelEntityData.setCitadelTag(enchanted, tag);
        if (!enchanted.level().isClientSide) {
            Citadel.sendMSGToAll(new PropertiesMessage("CitadelTagUpdate", tag, enchanted.getId()));
        } else {
            Citadel.sendMSGToServer(new PropertiesMessage("CitadelTagUpdate", tag, enchanted.getId()));
        }
    }

@Override
	public void tick() {
		Entity thrower = getOwner();
		if (!(thrower instanceof Player player) || !thrower.isAlive()) {
			if (!level().isClientSide) {
				discard();
			}
			return;
		}
		if (!level().isClientSide) {
			ItemStack stack = PlayerHelper.getFirstHeldItem(player, BotaniaItems.kingKey);
			boolean newCharging = !stack.isEmpty() && KeyOfTheKingsLawItem.isCharging(stack);
			if (isCharging() != newCharging) {
				setCharging(newCharging);
			}
		}

		Vec3 mot = getDeltaMovement();

		int liveTime = getLiveTicks();
		int delay = getDelay();
		boolean charging = isCharging() && liveTime == 0;

		if (charging) {
			setDeltaMovement(Vec3.ZERO);

			int chargeTime = getChargeTicks();
			setChargeTicks(chargeTime + 1);

			if (level().random.nextInt(20) == 0) {
				level().playSound(null, getX(), getY(), getZ(), BotaniaSounds.babylonSpawn, SoundSource.PLAYERS, 0.1F, 1F + level().random.nextFloat() * 3F);
			}
		} else {
			if (liveTime < delay) {
				setDeltaMovement(Vec3.ZERO);
			} else if (liveTime == delay) {
				Vec3 playerLook;
				BlockHitResult rtr = ToolCommons.raytraceFromEntity(player, 64, true);
				if (rtr.getType() != HitResult.Type.BLOCK) {
					playerLook = player.getLookAngle().scale(64).add(player.position());
				} else {
					playerLook = Vec3.atCenterOf(rtr.getBlockPos());
				}

				Vec3 thisVec = VecHelper.fromEntityCenter(this);

				mot = playerLook.subtract(thisVec.x, thisVec.y, thisVec.z).normalize().scale(2);
				level().playSound(null, getX(), getY(), getZ(), BotaniaSounds.babylonAttack, SoundSource.PLAYERS, 2F, 0.1F + level().random.nextFloat() * 3F);
			}

			if (!level().isClientSide) {
				setLiveTicks(liveTime + 1);
				AABB axis = new AABB(getX(), getY(), getZ(), xOld, yOld, zOld).inflate(2);
				List<LivingEntity> entities = level().getEntitiesOfClass(LivingEntity.class, axis);
				for (LivingEntity living : entities) {
					if (living == thrower) {
						continue;
					}

					if (living.hurtTime == 0) {
						living.hurt(level().damageSources().playerAttack(player), 20);
						onHit(new EntityHitResult(living));
						return;
					}
				}
			}
		}

		super.tick();

		// Apply after super tick so drag is not applied by super
		setDeltaMovement(mot);

		if (level().isClientSide && liveTime > delay) {
			WispParticleData data = WispParticleData.wisp(0.3F, 1F, 1F, 0F, 1);
			level().addParticle(data, getX(), getY(), getZ(), 0, -0F, 0);
		}

		if (!level().isClientSide && liveTime > 200 + delay) {
			discard();
		}
	}

